let collectEffectInteval = -212.5
cc.Class({
    extends: cc.Component,

    properties: {
        _turntableTriggerBar:null,   //转盘进度条
        _PrizePoolRoot:null,
        _turntableTriggerBarLock:false,
        _collectNode:null,  //收集物品的父节点
        _initTurntableTriggerBar:true,
        _PrizePoolRootInitY:0,
        _kuanggong:null,
        _jili:null,
    },

    onLoad(){
        this._turntableTriggerBar = cc.find("safe_node/slots/turntableTriggerBar",this.node)
        this._kuanggong = cc.find("safe_node/kuanggong",this.node)
        this._jili = cc.find("safe_node/jili",this.node)
        this._jili.active = false
        this._PrizePoolRoot = cc.find('safe_node/LMSlots_PrizePool_1',this.node)
        this._collectNode = cc.find("safe_node/collectNode",this.node)
        let collectButton = cc.find("iconRight/button",this._turntableTriggerBar)
        Global.btnClickEvent(collectButton,this.showMap,this)
        let turntableBarButton = cc.find("lock/button",this._turntableTriggerBar)
        Global.btnClickEvent(turntableBarButton,this.unlockTurntable,this)
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickQiQiu,this);
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)
        this.initTurntableTriggerBar()
    },

    start(){
        this._PrizePoolRootInitY = this._PrizePoolRoot.y
        // this._kuanggong.on("click",()=>{
        //     this._kuanggong.getComponent(cc.Button).interactable = false
        //     Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.coin)
        //     this.showkuanggongAnimation("click")
        // })
    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickQiQiu,false,this);
    },
    // LIFE-CYCLE CALLBACKS:

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    ShowGameview(bFree){
        this._kuanggong.active = !bFree
    },

    showTurntableTriggerBar(bFree){
        this._turntableTriggerBar.active = !bFree
    },

    initTurntableTriggerBar(){
        let mapInfo = cc.vv.gameData.getMapInfo()
        if(mapInfo){
            let curmult = cc.vv.gameData.GetBetIdx()
            let lockNode = cc.find("lock",this._turntableTriggerBar)
            if(curmult >= cc.vv.gameData.getNeedBet()){  //已经解锁
                lockNode.active = false
                this._turntableTriggerBarLock = false
            }else{
                lockNode.active = true
                this._turntableTriggerBarLock = true
            }
            let bar = cc.find("Bar",this._turntableTriggerBar)
            let barMask = cc.find("barMask",bar)
            let barPrograss = cc.find("barMask/bar",bar)
            let progress = mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt
            if(progress >= 1){  //初始化的时候如果进度条满了证明触发了转盘游戏，进度条归0一下
                progress = 0
            }
            let sjt_tou = cc.find("sjt_tou",barPrograss)
            if(progress > 0){
                sjt_tou.active = true
            }else{
                sjt_tou.active = false
            }
            let dstWidth = barMask.width*progress
            barPrograss.x = dstWidth - barMask.width
        }
    },

    changeTurntableTriggerBar(){
        let curmult = cc.vv.gameData.GetBetIdx()
        let lockNode = cc.find("lock",this._turntableTriggerBar)
        if(curmult >= cc.vv.gameData.getNeedBet()){  //已经解锁
            if(this._turntableTriggerBarLock){
                this._turntableTriggerBarLock = false
                let spine = cc.find("spine",lockNode)
                let spineSp = spine.getComponent(sp.Skeleton)
                spineSp.setAnimation(0,"animation3",false)
                if(!this._initTurntableTriggerBar){
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_unlock)
                }
                let turntableBarButton = cc.find("lock/button",this._turntableTriggerBar)
                turntableBarButton.getComponent(cc.Button).interactable = false
            }
        }else{
            if(!this._turntableTriggerBarLock){
                this._turntableTriggerBarLock = true
                lockNode.active = true
                let spine = cc.find("spine",lockNode)
                let spineSp = spine.getComponent(sp.Skeleton)
                spineSp.setAnimation(0,"animation1",false)
                spineSp.addAnimation(0,"animation2",true)
                if(!this._initTurntableTriggerBar){
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_lock)
                }
                let turntableBarButton = cc.find("lock/button",this._turntableTriggerBar)
                turntableBarButton.getComponent(cc.Button).interactable = true
            }
        }
        this._initTurntableTriggerBar = false
    },

    TrunTableTriggerBarVal(mapInfo){
        return new Promise(async (sucess,failed)=>{
            let curmult = cc.vv.gameData.GetBetIdx()
            if(curmult < cc.vv.gameData.getNeedBet()){  //已经锁
                sucess()
                return
            }
            let bar = cc.find("Bar",this._turntableTriggerBar)
            let barMask = cc.find("barMask",bar)
            let barPrograss = cc.find("barMask/bar",bar)
            let sjt_tou = cc.find("sjt_tou",barPrograss)
            let progress = mapInfo.progressData.totalCnt / mapInfo.progressData.needCnt
            if(progress > 0){
                sjt_tou.active = true
            }
            let jinHeZi = cc.vv.gameData.GetSlotsScript().findAllShouJiSymbol()
            if(jinHeZi.length > 0){
                let lihe = cc.find("giftBoxes",this._turntableTriggerBar)
                let lihePos = lihe.convertToWorldSpaceAR(cc.v2(0,0))
                let endPos = this._collectNode.convertToNodeSpaceAR(lihePos)
                for (let i = 0; i < jinHeZi.length; i++) {
                    const symbol = jinHeZi[i];
                    let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                    let finalPosition = this._collectNode.convertToNodeSpaceAR(position)
                    let tempSymbolNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("LMSlots_Symbol"))
                    cc.find("s1",tempSymbolNode).active = true
                    tempSymbolNode.parent = this._collectNode
                    tempSymbolNode.position = finalPosition
                    tempSymbolNode.scale = 1

                    // 第一个控制点为抛物线左半弧的中点
                    let q1x = finalPosition.x + (endPos.x - finalPosition.x) / 4;
                    let q1y = finalPosition.y + (endPos.y - finalPosition.y) / 4;
                    let dir = cc.v2(endPos.x - finalPosition.x,endPos.y - finalPosition.y)
                    dir.normalizeSelf()
                    let verticalDir = cc.v2(dir.y,-dir.x)
                    let q1 = cc.v2(q1x + verticalDir.x * 200, q1y + verticalDir.y * 200);
                    // 第二个控制点为整个抛物线的中点
                    let q2x = finalPosition.x + (endPos.x - finalPosition.x) / 2;
                    let q2y = finalPosition.y + (endPos.y - finalPosition.y) / 2;
                    let q2 = cc.v2(q2x + verticalDir.x * 200, q2y + verticalDir.y * 200);

                    cc.tween(tempSymbolNode).parallel(cc.tween().bezierTo(0.5,q1,q2,endPos,{easing:"quadIn"}),
                        cc.tween().to(0.5,{scale:0.5},{easing:"quadIn"})).start()
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_fly)
                await this.awaitTime(0.5)
                this._collectNode.removeAllChildren()
                let spine = cc.find("spine",lihe)
                let liheSpine = spine.getComponent(sp.Skeleton)
                liheSpine.setAnimation(0,"animation",false)
                liheSpine.addAnimation(0,"animation9",true)
                let liheEffect = cc.find("sjt_js",lihe)
                liheEffect.active = true
                liheEffect.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    liheEffect.active = false
                    liheEffect.getComponent(sp.Skeleton).setCompleteListener(null)
                })
                if(progress > 1){
                    progress = 1
                }
                let dstWidth = barMask.width*progress
                cc.tween(barPrograss).to(0.2,{x:dstWidth - barMask.width}).start()
                await this.awaitTime(0.2)
                if(progress >= 1){
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.collect_full)
                    let jiman = cc.find("jiman",bar)
                    jiman.active = true
                    let jimanSp = jiman.getComponent(sp.Skeleton)
                    jimanSp.setAnimation(0,"animation2",false)
                    jimanSp.setCompleteListener(()=>{
                        jiman.active = false
                        jimanSp.setCompleteListener(null)
                    })
                    liheSpine.setAnimation(0,"animation3",false)
                    liheSpine.addAnimation(0,"animation1",true)
                    await this.awaitTime(1.6)
                    this.scheduleOnce(()=>{
                        barPrograss.x = -barMask.width
                        sjt_tou.active = false
                    },2)
                }
            }
            sucess()
        })
    },

    /**
     * 修改节点和子节点的颜色
     * @param {cc.Node} node 
     * @param {cc.Color} color 
     */
    setNodeColor(node,color){
        if(node){
            node.color = color
            for (let i = 0; i < node.children.length; i++) {
                const element = node.children[i];
                element.color = color
            }
        }
    },

    /**
     * 收到点击气球狗
     * @param {*} msg 
     */
    async onRecvClickQiQiu(msg){
        if(msg.code == 200){
            if(msg.data.rtype === 1){

            }else if(msg.data.rtype === 2){
                cc.vv.gameData.getFreeWheel().onSpinWheel(msg.data.result)
            }
        }
    },

    /**
     * 押注更新
     * @param {*} data 
     */
    onEventTotalbetUpdated(data){
        this.changeTurntableTriggerBar()
    },

    async showMap(){
        if(cc.vv.gameData.GetSlotsScript()._isInFree){ //在免费游戏中不能修改押注
            return
        }
        if(cc.vv.gameData.GetSlotState() != 'idle'){
            return
        }
        if(cc.vv.gameData.GetAutoModelTime() > 0){
            return
        }
        let collectButton = cc.find("iconRight/button",this._turntableTriggerBar)
        collectButton.getComponent(cc.Button).interactable = false
        await cc.vv.gameData.getMapControl().show(cc.vv.gameData.getMapInfo())
        await this.awaitTime(2)
        collectButton.getComponent(cc.Button).interactable = true
    },

    unlockTurntable(){
        if(cc.vv.gameData.GetSlotsScript()._isInFree){ //在免费游戏中不能修改押注
            return
        }
        if(cc.vv.gameData.GetSlotState() != 'idle'){
            return
        }
        if(cc.vv.gameData.GetAutoModelTime() > 0){
            return
        }
        let turntableBarButton = cc.find("lock/button",this._turntableTriggerBar)
        if(cc.vv.gameData.getNeedBet() <= cc.vv.gameData._deskInfo.mults.length){
            turntableBarButton.getComponent(cc.Button).interactable = false
            let bottom = cc.vv.gameData.GetBottomScript()
            bottom.SetBetIdx(cc.vv.gameData.getNeedBet())
        }
    },

    showkuanggongAnimation(type){
        let kuanggongSp = this._kuanggong.getComponent(sp.Skeleton)
        switch (type) {
            case "normal":{
                // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.tihu1)
                // kuanggongSp.setAnimation(0,"animation2",false)
                // kuanggongSp.addAnimation(0,"animation1",true)
                kuanggongSp.setAnimation(0, "idle", true);
            }break;
            case "click":{
                // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.tihu2)
                // kuanggongSp.setAnimation(0,"animation3",false)
                // kuanggongSp.addAnimation(0,"animation1",true)
                // kuanggongSp.setCompleteListener(()=>{
                //     this._kuanggong.getComponent(cc.Button).interactable = true
                //     kuanggongSp.setCompleteListener(null)
                // })
            }break;   
        }
    },

    enter77(avgBet){
        cc.find('Canvas/safe_node/LMSlots_Subgame777').getComponent('LMSlots_Subgame777').showEnter(avgBet)
    },

    showJiLi(){
        return new Promise((success,failed)=>{
            this._jili.active = true
            this._jili.getComponent(sp.Skeleton).setCompleteListener(()=>{
                this._jili.active = false
                success()
                this._jili.getComponent(sp.Skeleton).setCompleteListener(null)
            })
            this.showkuanggongAnimation("normal")
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.notify)
        })
    },

});
