    showJackpotWinCoin(num,mult,jpid){
        return new Promise(async (sucess, failed)=>{
            switch (jpid) {
                case 1:{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_dialog_collect_show)
                }break
                case 2:{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.minor_dialog_collect_show)
                }break
                case 3:{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.major_dialog_collect_show)
                }break
                case 4:{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.grand_dialog_collect_show)
                }break
            }
            if(!mult){
                mult = 1
            }
            this.showWin()
            let show_popup = cc.find("showJackpotWinCoin",this.node)
            show_popup.active = true;
            let coinRoot = cc.find("coinRoot",show_popup)
            let coin = cc.find("coin",coinRoot)
            let collectBtn = cc.find("collectBtn",show_popup)
            let multNode = cc.find("multNode",show_popup)
            cc.find("mult",multNode).getComponent(cc.Label).string = mult+"X"
            let multEffect = cc.find("multEffect",show_popup)
            multEffect.active = false
            coinRoot.active = false
            collectBtn.active = false
            multNode.active = false
            let tanchuang = cc.find("wheeltanchuang",show_popup)
            tanchuang.active = false
            let cheSp = cc.find("wheelche",show_popup).getComponent(sp.Skeleton)
            cheSp.setAnimation(0,"animation1",false)
            cheSp.addAnimation(0,"animation2",true)
            await this.awaitTime(0.5)
            tanchuang.active = true
            let show_popupSp = tanchuang.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation"+(5-jpid)+"_1",false)
            show_popupSp.addAnimation(0,"animation"+(5-jpid)+"_2",true)
            await this.awaitTime(0.5)
            coinRoot.active = true
            coinRoot.scale = 0
            cc.tween(coinRoot).to(0.3,{scale:1},{easing:"backOut"}).start()
            if(mult > 1){
                multNode.active = true
                multNode.scale = 0
                cc.tween(multNode).to(0.2,{scale:1},{easing:"backOut"}).start()
            }
            let firstNum = num / mult
            this._startAddCoin = true
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.win_rollup)
            Global.doRoallNumEff(coin,Math.floor(firstNum*0.1),firstNum,2,async ()=>{
                this._startAddCoin = false
                if(mult > 1){
                    let finalPosition = multNode.position
                    let endPos = coinRoot.position
                    let tempMult = cc.instantiate(multNode)
                    tempMult.position = finalPosition
                    tempMult.parent = multNode.parent
                    multNode.active = false
                    // 把角度转换为弧度
                    let radian = 60 * 3.14159 / 180;
                    // 第一个控制点为抛物线左半弧的中点
                    let q1x = finalPosition.x + (endPos.x - finalPosition.x) / 4;
                    let q1 = cc.v2(q1x, 50 + finalPosition.y + Math.cos(radian) * q1x);
                    // 第二个控制点为整个抛物线的中点
                    let q2x = finalPosition.x + (endPos.x - finalPosition.x) / 2;
                    let q2 = cc.v2(q2x, 50 + finalPosition.y + Math.cos(radian) * q2x);

                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.multiply)
                    cc.tween(tempMult).bezierTo(0.5,q1,q2,endPos,{easing:"quadIn"}).call(()=>{
                        tempMult.parent = null
                        multEffect.active = true
                        let multEffectSp = multEffect.getComponent(sp.Skeleton)
                        multEffectSp.setCompleteListener(()=>{
                            multEffect.active = false
                            multEffectSp.setCompleteListener(null)
                        })
                    }).start()
                    await this.awaitTime(0.5)
                    this._startAddCoin = true
                    ///倍数跳动
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.win_rollup)
                    Global.doRoallNumEff(coin,firstNum,num,2,()=>{
                        this._startAddCoin = false
                    },null,0,true)
                }
            },null,0,true);
            let btnDelay = 0
            if(mult > 1){
                btnDelay = 3
            }
            await this.awaitTime(btnDelay)
            collectBtn.active = true
            collectBtn.scale = 0
            cc.tween(collectBtn).to(0.3,{scale:1},{easing:"backOut"}).start()
            await this.awaitTime(0.3);
            let self = this;
            let clickFunc = async ()=>{
                collectBtn.getComponent(cc.Button).interactable = false
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click)
                if(self._startAddCoin){
                    self._startAddCoin = false
                    coin.stopAllActions()
                    let winCoinLabel = coin.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(num)
                    Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.win_rollup)
                    await self.awaitTime(0.2)
                }
                show_popupSp.setAnimation(0,"animation"+(5-jpid)+"_3",false)
                // await this.awaitTime(0.2)
                cc.tween(collectBtn).to(0.3,{scale:0},{easing:"backIn"}).start()
                cc.tween(coinRoot).to(0.3,{scale:0},{easing:"backIn"}).start()
                await self.awaitTime(0.5)
                cheSp.setAnimation(0,"animation3",false)
                cheSp.setCompleteListener(()=>{
                    show_popup.active = false
                    self.hideWin(()=>{
                        sucess()
                    })
                    cheSp.setCompleteListener(null)
                })
            };
            cc.vv.gameData.checkAutoPlay(collectBtn, clickFunc);
            collectBtn.getComponent(cc.Button).interactable = true
            collectBtn.off("click");
            collectBtn.on("click", async ()=>{
                collectBtn.stopAllActions();
                clickFunc();
            })
        });
    },

