/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //重写
    SetSymbolIdx:function(idx){
        this._symbolIdx = idx;
        if(this._id === 2){
            this.node.zIndex = 150 - idx;
        }else{
            this.node.zIndex = 100 - idx;
        }
    },

    //赢钱动画
    playWinAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "win";
            if(this._showNode){
                this._showNode.active = false
            }
            if(id === 102){  //倍数wild
                this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
                this._showNode.active = true
                if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                    this.node.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                    let nodeSp = this._showNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                    }
                }
            }else{
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
                topShowNode.active = true
                if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                    aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                    let nodeSp = topShowNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                    }
                }
            }
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },

    //重写
    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            this.OnReelBounsAction(aniNode)
            
            if(cfg.symbol[id].stop_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                    if(cfg.symbol[id].idle_ani){
                        nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                    }
                }
            }
        }
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "idle";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,false)
                    if(cfg.symbol[id].idle_ani){
                        nodeSp.addAnimation(0,cfg.symbol[id].idle_ani.name,true)
                    }
                }
            }
        }
        return isPlay
    },

    //待机动画
    playidleAnimation(isStop){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            this._state = "idle";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(isStop){
                this.OnReelBounsAction(aniNode)
            }
            if(cfg.symbol[id].idle_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }
        }
        return isPlay
    },

    OnReelBounsAction:function(node){
        let cfg = cc.vv.gameData.getGameCfg()
        let distance = cfg.bounceInfo ? cfg.bounceInfo.distance : 30
        let time = cfg.bounceInfo ? cfg.bounceInfo.time : 0.3
        //考虑到倍率问题
        time = time/cc.vv.gameData.GetSlotsScript().GetTimeScale() 
        
        cc.tween(node)
        .to(time,{position:cc.v2(node.x,node.y + distance)})
        .start()
    },

    //改变bonus图标
    changeBonus(id){
        if(this._id !== 3){  //不是bonus图标返回
            return false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        let cloneNode = cc.instantiate(this.node)
        let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
        cloneNode.parent = this._topAniNode
        cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
        for (let i = 0;i < cloneNode.children.length;i++){
            const element = cloneNode.children[i]
            element.active = false
        }
        let topShowNode = cc.find(cfg.symbol[this._id].win_node,cloneNode)
        topShowNode.active = true
        let topShowNodeSp = topShowNode.getComponent(sp.Skeleton)
        topShowNodeSp.setAnimation(0,cfg.symbol[this._id].open_ani,false)
        topShowNodeSp.setCompleteListener(()=>{
            cloneNode.parent = null
            topShowNodeSp.setCompleteListener(null)
        })
        this.ShowById(id)
        return true
    },

    changeGoldWild(){
        if(this._id !== 1){  //不是wild图标返回
            return false
        }
        this.setAnimationToTop(false)
        this.ShowById(101)
    },

    changeGoldWildAnimation(){
        if(this._id !== 1){  //不是wild图标返回
            return false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        this._id = 101
        if(this._showNode){
            this._showNode.active = false
        }
        this._showNode = cc.find(cfg.symbol[this._id].win_node,this.node)
        this._showNode.active = true
        this._showNode.getComponent(sp.Skeleton).setAnimation(0,"animation9",true)
        let wildguding = cc.find("wildguding",this.node)
        let gudingEffect = cc.instantiate(wildguding)
        gudingEffect.active = true
        gudingEffect.parent = cc.vv.gameData.getManage()._collectNode
        let position = wildguding.convertToWorldSpaceAR(cc.v2(0,0))
        let finalPos = cc.vv.gameData.getManage()._collectNode.convertToNodeSpaceAR(position)
        gudingEffect.position = finalPos
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.stickywild)
        gudingEffect.getComponent(sp.Skeleton).setAnimation(0,"animation",false)
        gudingEffect.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._showNode.getComponent(sp.Skeleton).setAnimation(0,"animation5",false)
            this._showNode.getComponent(sp.Skeleton).addAnimation(0,"animation7",true)
            gudingEffect.getComponent(sp.Skeleton).setCompleteListener(null)
            gudingEffect.parent = null
        })
    },

    /**
     * 获取随机的符号表，可重写次函数根据需要配置免费游戏的符号表
     *
     */
    GetRandomCfg:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let isFree = cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()
        if(isFree && cfg.cardmapfree) {
            if(cc.vv.gameData.GetSlotsScript()._randomWild){
                return cfg.cardmaprandomwild
            }
            return cfg.cardmapfree
        }
        return cfg.cardmap
    },

    //显示随机符号
    ShowInitSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randVal
        let randomcfg = cfg.cardmaprandomwild
        if(randomcfg){
            let reelrandomCfg = randomcfg[this._reelIdx+1]
            if(reelrandomCfg){
                //gamedata中记录了当前列随机到符号表的序号了，只需要一个个往下随机战士就好
                let randIdx = cc.vv.gameData.GetReelRandomIdx(this._reelIdx)
                if(randIdx){
                    //如果没有就随机一个开始值，如果每次都从0开始，就每次进去游戏都是那几个图标
                    randIdx = Global.random(1,reelrandomCfg.length)-1
                }
                randVal = reelrandomCfg[randIdx]
                if(!randVal){ //如果取到最后了就从头开始取
                    randIdx = 0
                    randVal = reelrandomCfg[randIdx]
                }

                cc.vv.gameData.SetReelRandomIdx(this._reelIdx,++randIdx)
            }
        }
        else{//兼容旧的配置数据
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            randVal = cfg.randomSymbols[randIdx-1]
        }
        this.ShowById(randVal)

    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let randVal
        let randomcfg = this.GetRandomCfg()
        if(randomcfg){
            let reelrandomCfg = randomcfg[this._reelIdx+1]
            if(reelrandomCfg){
                //gamedata中记录了当前列随机到符号表的序号了，只需要一个个往下随机战士就好
                let randIdx = cc.vv.gameData.GetReelRandomIdx(this._reelIdx)
                if(randIdx){
                    //如果没有就随机一个开始值，如果每次都从0开始，就每次进去游戏都是那几个图标
                    randIdx = Global.random(1,reelrandomCfg.length)-1
                }
                randVal = reelrandomCfg[randIdx]
                if(!randVal){ //如果取到最后了就从头开始取
                    randIdx = 0
                    randVal = reelrandomCfg[randIdx]
                }

                cc.vv.gameData.SetReelRandomIdx(this._reelIdx,++randIdx)
            }
        }
        else{//兼容旧的配置数据
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            randVal = cfg.randomSymbols[randIdx-1]
        }
        this.ShowById(randVal)
        return randVal
    },

    playCloseAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        this.node.active = true
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].close_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].close_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].close_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].close_ani.name,false)
                }
            }
        }
    },

    playOpenAnimation(mult){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].open_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            cc.find("wildNum",this.node).getComponent(cc.Label).string = mult+"X"

            if(cfg.symbol[id].open_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].open_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].open_ani.name,false)
                }
            }
        }
    },

    changeMultWild(mult){
        this.ShowById(102)
        cc.find("wildNum",this.node).active = true
        cc.find("wildNum",this.node).getComponent(cc.Label).string = mult+"X"
    },

    showLanSeMuMen(mult){
        this.ShowById(103)
        if(this._showNode){
            this._showNode.active = false
        }
        cc.find("s14",this.node).active = true
        cc.find("wildNum",this.node).active = true
        cc.find("wildNum",this.node).getComponent(cc.Label).string = mult+"X"
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){
        this._super(id,data)
        cc.find("wildNum",this.node).active = false
    },

    // update (dt) {},
});
