
cc.Class({
    extends: cc.Component,

    properties: {
        kuangche:{
            default:null,
            type:cc.Node
        },
        zhadan:{
            default:null,
            type:cc.Node
        },
        jinkuai:{
            default:null,
            type:cc.Node
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    async showKuangChe1(callBack){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_freein)
        this.kuangche.active = true
        let show_popupSp = this.kuangche.getComponent(sp.Skeleton)
        show_popupSp.setAnimation(0,"skill",false)
        show_popupSp.setCompleteListener(()=>{
            this.kuangche.active = false
            show_popupSp.setCompleteListener(null)
        })
        await this.awaitTime(1.8)
        if(callBack){
            callBack()
        }
    },

    async showKuangChe2(callBack){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_freeout)
        this.kuangche.active = true
        let show_popupSp = this.kuangche.getComponent(sp.Skeleton)
        show_popupSp.setAnimation(0,"skill",false)
        show_popupSp.setCompleteListener(()=>{
            this.kuangche.active = false
            show_popupSp.setCompleteListener(null)
        })
        await this.awaitTime(1.8)
        if(callBack){
            callBack()
        }
    },

    showZhaDan1(){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_wheelin)
            this.zhadan.active = true
            cc.vv.gameData.GetSlotsScript().showMask(true)
            let show_popupSp = this.zhadan.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation1",false)
            show_popupSp.setCompleteListener(()=>{
                this.zhadan.active = false
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(4)
            cc.vv.gameData.GetSlotsScript().showMask(false)
            sucess()
        });
    },

    showZhaDan2(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_wheelout)
            this.zhadan.active = true
            let show_popupSp = this.zhadan.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation2",false)
            show_popupSp.setCompleteListener(()=>{
                this.zhadan.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
        });
    },

    showJinKua(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_map)
            this.jinkuai.active = true
            let show_popupSp = this.jinkuai.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.jinkuai.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(0.8)
            if(callBack){
                callBack()
            }
        });
    },

    // update (dt) {},
});
