    findAllShouJiSymbol(){
        let ret = []
        if(this._isInFree){
            for (let i = 0; i < this._reelsFree.length; i++) {
                const reel = this._reelsFree[i];
                for (let j = 0; j < reel._symbols.length - 1; j++) {
                    const symbol = reel._symbols[j];
                    if(symbol._id === 1){
                        ret.push(symbol)
                    }
                }
            }
        }else{
            for (let i = 0; i < this._reels.length; i++) {
                const reel = this._reels[i];
                for (let j = 0; j < reel._symbols.length - 1; j++) {
                    const symbol = reel._symbols[j];
                    if(symbol._id === 1){
                        ret.push(symbol)
                    }
                }
            }
        }
        return ret
    },

